package com.gymmind.nutrition.api; import com.gymmind.nutrition.application.*; import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.CurrentActorProvider; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/v1/nutrition") public class NutritionController { final NutritionPlanService plans; final NutritionRecordService records; final NutritionFoodService foods; final CurrentActorProvider actors; public NutritionController(NutritionPlanService p,NutritionRecordService r,NutritionFoodService f,CurrentActorProvider a){plans=p;records=r;foods=f;actors=a;} @PostMapping("/plans") @ResponseStatus(HttpStatus.CREATED) public ApiResponse<NutritionPlanView> plan(@Valid @RequestBody PlanRequest r){return ApiResponse.success(plans.create(actors.requireCurrent(),new CreateNutritionPlanCommand(null,r.memberId(),r.calories(),r.protein(),r.carbohydrate(),r.fat(),r.description())));} @PostMapping("/records") @ResponseStatus(HttpStatus.CREATED) public ApiResponse<NutritionRecordView> record(@Valid @RequestBody RecordRequest r){return ApiResponse.success(records.create(actors.requireCurrent(),new CreateNutritionRecordCommand(null,r.recordDate(),r.calories(),r.protein(),r.carbohydrate(),r.fat(),r.notes())));} @PostMapping("/foods") @ResponseStatus(HttpStatus.CREATED) public ApiResponse<NutritionFoodView> food(@Valid @RequestBody FoodRequest r){return ApiResponse.success(foods.create(actors.requireCurrent(),new CreateNutritionFoodCommand(null,r.name(),r.calories(),r.protein(),r.carbohydrate(),r.fat(),r.servingSize())));} public record PlanRequest(Long memberId,@Min(0) double calories,@Min(0) double protein,@Min(0) double carbohydrate,@Min(0) double fat,@NotBlank String description){} public record RecordRequest(@NotNull LocalDate recordDate,@Min(0) double calories,@Min(0) double protein,@Min(0) double carbohydrate,@Min(0) double fat,@NotBlank String notes){} public record FoodRequest(@NotBlank String name,@Min(0) double calories,@Min(0) double protein,@Min(0) double carbohydrate,@Min(0) double fat,@NotBlank String servingSize){} }
